**What this code covers**

- Get the weather in Hyderabad, get Tesla stock price,
- You are a helpful AI assistant.

**Defines:** `get_weather()`, `get_stock_price()`, `web_search()`, `get_current_time()`

```python
import openai
import json
from datetime import datetime
from groq import Groq

client = Groq(api_key=os.environ.get("GROQ_API_KEY"))
```

```python
def get_weather(city: str) -> dict:
    return {"city": city, "temp": "32°C", "condition": "Sunny"}

def get_stock_price(symbol: str) -> dict:
    prices = {"AAPL": 189.5, "GOOGL": 175.2, "TSLA": 245.0}
    return {"symbol": symbol, "price": prices.get(symbol, 100.0), "currency": "USD"}

def web_search(query: str) -> dict:

    return {
        "query": query,
        "results": [
            "Result 1",
            "Result 2",
            "Result 3"
        ]
    }

def get_current_time() -> dict:
    return {"time": datetime.now().strftime("%H:%M:%S"), "date": datetime.now().strftime("%Y-%m-%d")}
```

```python
tools = [
    {
        "type": "function",
        "function": {
            "name": "get_weather",
            "description": "Get current weather for a city",
            "parameters": {
                "type": "object",
                "properties": {
                    "city": {"type": "string", "description": "City name"}
                },
                "required": ["city"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "get_stock_price",
            "description": "Get current stock price for a stock symbol like AAPL, GOOGL, TSLA",
            "parameters": {
                "type": "object",
                "properties": {
                    "symbol": {"type": "string", "description": "Stock ticker symbol, e.g. AAPL"}
                },
                "required": ["symbol"]
            }
        }
    },
   {
    "type": "function",
    "function": {
        "name": "web_search",
        "description": "Search the internet for latest information",
        "parameters": {
            "type": "object",
            "properties": {
                "query": {
                    "type": "string",
                    "description": "Search query"
                }
            },
            "required": ["query"]
        }
    }
},
    {
        "type": "function",
        "function": {
            "name": "get_current_time",
            "description": "Get the current date and time",
            "parameters": {
                "type": "object",
                "properties": {}
            }
        }
    }
]
```

```python
available_functions = {
    "get_weather": get_weather,
    "get_stock_price": get_stock_price,
    "get_current_time": get_current_time,
    "web_search": web_search
}
```

```python
user_query = """
Get the weather in Hyderabad,
get Tesla stock price,
"""
```

```python
messages = [
    {
        "role": "system",
        "content": """
You are a helpful AI assistant.

Use tools whenever needed.

You can call multiple tools.
"""
    },
    {
        "role": "user",
        "content": user_query
    }
]

while True:
    response = client.chat.completions.create(
        model="openai/gpt-oss-20b",
        messages=messages,
        tools=tools,
        max_tokens=500
    )

    response_message = response.choices[0].message
    messages.append(response_message)

    if not response_message.tool_calls:
        print("Final response from model:")
        print(response_message.content)
        break

    for tool_call in response_message.tool_calls:
        function_name = tool_call.function.name
        print(f"calling tool: {function_name}")
        tool_function = available_functions.get(function_name)

        if tool_function:
            tool_args = json.loads(tool_call.function.arguments)
            tool_result = tool_function(**tool_args)
            print(f"Tool result: {tool_result}")

            messages.append({
                "role": "tool",
                "tool_call_id": tool_call.id,
                "content": json.dumps(tool_result)
            })
        else:
            print(f"Tool {function_name} not found in available functions.")
            messages.append({
                "role": "tool",
                "tool_call_id": tool_call.id,
                "content": json.dumps({"error": "Tool not found"})
            })
```

